// src/core/memory/memory.schemas.ts
import { z } from 'zod';

export const updateFromIntentSchema = z.object({
  intent: z.string().min(1, 'Intent é obrigatória'),
  parameters: z.record(z.any()),
  entityType: z.string().optional(),
  entityId: z.string().uuid('ID da entidade inválido').optional(),
  entityName: z.string().optional(),
});

export const registerInteractionSchema = z.object({
  entityId: z.string().min(1, 'ID da entidade é obrigatório'),
  entityType: z.string().min(1, 'Tipo da entidade é obrigatório'),
  entityName: z.string().optional(),
  metadata: z.record(z.any()).optional(),
});
















